use vstd::prelude::*;

verus! {

/// Specification for converting a fixed-size array of 10 booleans
/// into a dynamic Vec<bool>, preserving order and values.
fn array_to_sequence(arr: &[bool; 10]) -> (res: Vec<bool>)
    ensures
        // The resulting vector has exactly length 10
        res.len() == 10,
        // For each index 0 <= i < 10, the value is preserved
        forall |i: usize| i < 10 ==> res.index(i) == arr[i],
{
    // start with an empty Vec
    let mut res: Vec<bool> = Vec::new();
    // we know in advance we will need 10 slots
    res.reserve(10);

    let mut i: usize = 0;
    while i < 10
        invariant
            // loop counter stays in bounds
            i <= 10,
            // res.len() tracks how many we've pushed so far
            res.len() == i,
            // for each j < i, res[j] == arr[j]
            forall |j: usize| j < i ==> res.index(j) == arr[j],
        decreases 10 - i
    {
        // read the next array element
        let value = arr[i];
        // push it onto the Vec
        res.push(value);
        // now prove that the newly‐pushed element is in place
        assert(res.index(i) == value);
        // advance
        i += 1;
    }

    // at this point i == 10 and res.len() == 10,
    // and we have preserved each element, so the postcondition holds
    res
}

}